WITH v AS (SELECT task_id, transitioned_at, MAX(updated_at) AS last_edit_at, COUNT(*) AS versions FROM task_history WHERE world_id = 'world_43fcdce6b6a64c599c412134b03ba9e6' GROUP BY task_id, transitioned_at), t AS (SELECT DISTINCT ON (task_id, transitioned_at) task_id, transitioned_at, task_status_id, transitioned_by, owned_by, created_by, task_name FROM task_history WHERE world_id = 'world_43fcdce6b6a64c599c412134b03ba9e6' ORDER BY task_id, transitioned_at, version ASC), e AS (SELECT task_id, task_name, created_by, ROW_NUMBER() OVER (PARTITION BY task_id ORDER BY transitioned_at) AS seq, LAG(task_status_id) OVER (PARTITION BY task_id ORDER BY transitioned_at) AS prev_status_id, task_status_id AS status_id, LEAD(task_status_id) OVER (PARTITION BY task_id ORDER BY transitioned_at) AS next_status_id, transitioned_at AS entered_at, LEAD(transitioned_at) OVER (PARTITION BY task_id ORDER BY transitioned_at) AS exited_at, transitioned_by AS entered_by_id, LEAD(transitioned_by) OVER (PARTITION BY task_id ORDER BY transitioned_at) AS exited_by_id, owned_by AS owner_id, v.last_edit_at, v.versions FROM t JOIN v USING (task_id, transitioned_at)) SELECT e.task_id, e.task_name, cu.email AS creator, e.seq, e.prev_status_id, e.status_id, e.next_status_id, e.entered_at, e.exited_at, eb.email AS entered_by, xb.email AS exited_by, ow.email AS owner, ROUND((EXTRACT(EPOCH FROM (COALESCE(e.exited_at, NOW()) - e.entered_at)) / 3600.0)::numeric, 3) AS hours_in_status, e.created_by AS creator_id, e.entered_by_id, e.exited_by_id, e.owner_id, e.last_edit_at, e.versions FROM e LEFT JOIN users cu ON cu.user_id = e.created_by LEFT JOIN users eb ON eb.user_id = e.entered_by_id LEFT JOIN users xb ON xb.user_id = e.exited_by_id LEFT JOIN users ow ON ow.user_id = e.owner_id ORDER BY e.task_id, e.seq LIMIT 10000
